 "content": "def transform(grid):
    """Copy the non-background pattern into the zero rectangle, mirrored left-right."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # The blank destination is the axis-aligned bounding box of the zero cells.
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    if not zeros:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, _ in zeros), max(r for r, _ in zeros)
    c0, c1 = min(c for _, c in zeros), max(c for _, c in zeros)
    rh, rw = r1 - r0 + 1, c1 - c0 + 1

    # Locate a same-sized pattern region outside the background and destination.
    # ARC instances place the source motif above the blank target panel.
    candidates = []
    for sr in range(h - rh + 1):
        for sc in range(w - rw + 1):
            if not (sr + rh <= r0 or sr >= r1 + 1 or sc + rw <= c0 or sc >= c1 + 1):
                continue
            patch = [grid[sr + dr][sc:sc + rw] for dr in range(rh)]
            if all(value != background for row in patch for value in row):
                candidates.append((sr, sc, patch))
    if not candidates:
        return [row[:] for row in grid]
    # Prefer the topmost, then leftmost complete motif.
    _, _, motif = min(candidates, key=lambda item: (item[0], item[1]))

    out = [row[:] for row in grid]
    for dr in range(rh):
        for dc in range(rw):
            out[r0 + dr][c0 + dc] = motif[dr][rw - 1 - dc]
    return out


